from typing import Iterator

class BoundedList:
    """A list that enforces a maximum size."""
    def __init__(self, max_size: int):
        self.max_size = max_size
        self._items: list = []

    def __len__(self) -> int:
        return len(self._items)

    def __getitem__(self, index):
        return self._items[index]  # supports slicing too

    def __setitem__(self, index, value):
        self._items[index] = value

    def __contains__(self, item) -> bool:
        return item in self._items

    def __iter__(self) -> Iterator:
        return iter(self._items)

    def __repr__(self) -> str:
        return f'BoundedList(max_size={self.max_size}, items={self._items!r})'

    def append(self, item):
        if len(self._items) >= self.max_size:
            raise OverflowError(f'BoundedList max size {self.max_size} reached')
        self._items.append(item)

# Now it works with all Python built-ins
bl = BoundedList(3)
bl.append(1)
bl.append(2)
print(len(bl))       # 2  — __len__
print(1 in bl)       # True  — __contains__
for item in bl:      # __iter__
    print(item)
print(bl[0])         # 1  — __getitem__

# __call__ example
class Retry:
    def __init__(self, max_attempts: int):
        self.max_attempts = max_attempts

    def __call__(self, func):
        """Use as a decorator."""
        def wrapper(*args, **kwargs):
            for attempt in range(self.max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == self.max_attempts - 1:
                        raise
        return wrapper

retry3 = Retry(3)
@retry3
def flaky_request(): ...
